import java.util.*;

class Solution {
  public long countPaths(int n, int[][] edges) {
    boolean[] prime = new boolean[n + 1];
    Arrays.fill(prime, true);
    prime[0] = prime[1] = false;
    for (int i = 2; i * i <= n; i++)
      if (prime[i]) for (int j = i * i; j <= n; j += i) prime[j] = false;
    List<Integer>[] g = new List[n + 1];
    for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    int[] comp = new int[n + 1];
    List<Integer> sizes = new ArrayList<>();
    int id = 0;
    for (int i = 1; i <= n; i++)
      if (!prime[i] && comp[i] == 0) {
        id++;
        int size = 0;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(i);
        comp[i] = id;
        while (!q.isEmpty()) {
          int u = q.remove();
          size++;
          for (int v : g[u])
            if (!prime[v] && comp[v] == 0) {
              comp[v] = id;
              q.add(v);
            }
        }
        sizes.add(size);
      }
    long ans = 0;
    for (int p = 1; p <= n; p++)
      if (prime[p]) {
        long seen = 0;
        for (int v : g[p])
          if (!prime[v]) {
            int size = sizes.get(comp[v] - 1);
            ans += (long) size * seen;
            seen += size;
          }
        ans += seen;
      }
    return ans;
  }
}
